import itertools

def has_cycle_of_length_less_than_7(adj, n):
    # Check for cycles of length 3, 4, 5, 6
    for start_node in range(n):
        # BFS to find shortest cycle
        queue = [(start_node, -1, 0)] # (current_node, parent, depth)
        visited = {start_node: 0}
        while queue:
            u, p, d = queue.pop(0)
            if d >= 6:
                continue
            for v in adj[u]:
                if v == p:
                    continue
                if v in visited:
                    if visited[v] + d + 1 < 7:
                        return True
                else:
                    visited[v] = d + 1
                    queue.append((v, u, d + 1))
    return False

